pub fn source_page(row: Row) -> Vec<u8> {
    let mut bytes = vec![0xcc; PAGE];
    bytes[(B - SOURCE) as usize..(B - SOURCE) as usize + FUNCTION.len()].copy_from_slice(FUNCTION);
    bytes[(CALLER - SOURCE) as usize..(CALLER - SOURCE) as usize + 5].copy_from_slice(&row.caller);
    bytes
}
