pub fn refused(f: impl FnOnce()) {
    // This helper runs only in one exact-name isolated test child. No other
    // test body or hook installer runs concurrently. Forward unrelated-thread
    // panics; silence only the negative whose unwind this thread expects.
    let owner = std::thread::current().id();
    let previous = std::sync::Arc::new(std::panic::take_hook());
    let forward = std::sync::Arc::clone(&previous);
    std::panic::set_hook(Box::new(move |info| {
        if std::thread::current().id() != owner {
            forward(info);
        }
    }));
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(f));
    // Restore after catch_unwind, when this thread is no longer panicking:
    // set_hook/take_hook are forbidden during unwinding, so a Drop guard would
    // be unsafe for that purpose. All negative work is inside the catch above.
    // Taking/dropping the installed wrapper removes its sole extra Arc owner;
    // any other-thread hook invocation has completed before it can be removed.
    let installed = std::panic::take_hook();
    drop(installed);
    let previous = std::sync::Arc::try_unwrap(previous)
        .unwrap_or_else(|_| panic!("expected-panic hook retained unexpectedly"));
    std::panic::set_hook(previous);
    assert!(result.is_err(), "required mutant was accepted");
}
